# Analyze demo patterns to learn transformation rule
def analyze_demos(demos):
    if not demos:
        return {"status": "no_demos"}

    results = []
    for i, demo in enumerate(demos):
        inp = demo['input']
        out = demo['output']
        results.append({
            'idx': i,
            'inp_shape': (len(inp), len(inp[0]) if inp else 0),
            'out_shape': (len(out), len(out[0]) if out else 0),
            'inp_size': len(inp),
            'out_size': len(out)
        })
    return {"status": "ok", "results": results, "count": len(demos)}

